+ ranger:{name:'Ranger',role:'Wildwood scout · Rook',kind:'rook',hp:8,max:8,damage:2,skill:'Longshot',skillIcon:'➶',skillDesc:'Strike an enemy in a straight line, up to 4 tiles away.',range:4,ability:'shot'},
+ duelist:{name:'Duelist',role:'Oathblade · Knight',kind:'knight',hp:8,max:8,damage:3,skill:'Phantom Lunge',skillIcon:'⚔',skillDesc:'Blink to an enemy in an L-shape and deal 4 damage.',range:3,ability:'lunge'},
