function showModal(icon,title,text,button){$('modalIcon').textContent=icon;$('modalTitle').textContent=title;$('modalText').textContent=text;$('modalButton').textContent=button;$('modal').classList.add('show');}
function distance(a,b){return Math.max(Math.abs(a.row-b.row),Math.abs(a.col-b.col));}
function aiTurn(){if(gameOver||turn!=='enemy')return;let foes=alive('player'),friends=alive('enemy'),choices=[];
 for(const u of friends){for(const [r,c] of movementTargets(u)){let v=at(r,c),score=0;if(v){score=2.4+u.damage*.3+(v.hp<=u.damage?8:0);if(v.type==='warlord')score+=4;}else{let before=Math.min(...foes.map(f=>distance(u,f))),after=Math.min(...foes.map(f=>distance({row:r,col:c},f)));score=(before-after)*1.25+(Math.random()*.6);if(u.type==='sentinel'&&r>3)score+=.1;}choices.push({u,r,c,score,kind:'move'});}
 if(u.cd===0){for(const [r,c] of skillTargets(u)){let v=at(r,c),score=0;if(u.type==='warlord')score=1+(v.max-v.hp)*.42;else if(u.type==='sentinel')score=v.shield?-.5:1.3+(6-v.hp)*.1;else{let dmg=u.type==='duelist'?4:u.type==='ranger'?3:4;score=3+(v.hp<=dmg?8:0)+(v.type==='warlord'?4:0);}choices.push({u,r,c,score:score+Math.random()*.45,kind:'skill'});}}
 }
 choices.sort((a,b)=>b.score-a.score);let best=choices[0];if(!best){turn='player';round++;actionTaken=false;undoState=null;for(const u of alive('player'))u.cd=Math.max(0,u.cd-1);log(`Round ${round} — your company is ready.`);render();return;}
 if(best.kind==='skill')performSkill(best.u,at(best.r,best.c),true);else performMove(best.u,best.r,best.c,true);
}
function undo(){if(!undoState||turn!=='enemy'||gameOver)return;clearTimeout(aiTimer);let s=undoState;units=s.units;selected=units.find(u=>u.id===s.selectedId)||null;turn='player';round=s.round;kills=s.kills;enemyKills=s.enemyKills;lastMove=s.lastMove;actionTaken=false;undoState=null;skillMode=false;$('feed').innerHTML='';log('Your last command was recalled. Choose another action.');render();toast('Action undone.');}
function passTurn(){if(turn!=='player'||actionTaken||gameOver)return;snapshot();actionTaken=true;turn='enemy';selected=null;for(const u of alive('enemy'))u.cd=Math.max(0,u.cd-1);log('You hold your position and pass the initiative.');render();aiTimer=setTimeout(aiTurn,500);}
