$('modalButton').addEventListener('click',()=>{if(gameOver)freshGame();else $('modal').classList.remove('show');});
$('helpBtn').addEventListener('click',()=>showModal('✦','How to play','Select a hero, then tap a highlighted square to move or attack. Each turn allows one action. Select a hero and activate their skill from the command panel to heal, shield, or strike at range. Red rings mark attack targets; green dots mark movement. Defeat the enemy Warlord to win.','Back to battle'));
